<?php
session_start();
require_once 'database.php';

if (!isset($_SESSION['loggedinEmail'])) {
    header('Location: login.php');
    exit;
}

if (($_SESSION['userRole'] ?? 'user') === 'admin') {
    header('Location: admin.php');
    exit;
}

$userId = (int) ($_SESSION['userId'] ?? 0);
$account = $conn->query("SELECT full_name, email FROM users WHERE id = $userId")->fetch_assoc();
$jobs = $conn->query('SELECT id, title, company, location, job_type, created_at FROM jobs ORDER BY created_at DESC LIMIT 4');
$jobCount = (int) ($conn->query('SELECT COUNT(*) total FROM jobs')->fetch_assoc()['total'] ?? 0);
$savedCount = (int) ($conn->query("SELECT COUNT(*) total FROM saved_jobs WHERE user_id = $userId")->fetch_assoc()['total'] ?? 0);
?>
